mapper.select:
SELECT T3.FINPROD_ID, T3.FINPROD_TYPE, T3.FINPROD_TYPE2, T3.FINPROD_MARKET_ID, T3.FINPROD_NAME, T3.FINPROD_ABBR, T3.ISSUE_AMT, T3.VDATE, T1.EFF_DATE, T1.CALC_TYPE, T1.BASE_TYPE, T1.BASE_DATE_TYPE, T1.BASIS, T1.YIELD*100 YIELD, T1.IS_INITIAL, T1.BRANCH, T2.CASH_ID, T2.FEE_ID FROM FIN_CASH_CALC_RULE T1 INNER JOIN FIN_CASH_INFO T2 ON T2.CASH_ID = T1.CASH_ID LEFT JOIN FIN_PRODUCT T3 ON T3.FINPROD_ID = T1.FINPROD_ID AND T2.FINPROD_ID = T3.FINPROD_ID
AND T2.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
and T2.CASH_TYPE_2 in ('C11','C12','C13','C14')
AND T2.CASH_TYPE_1 = #{cashType1,jdbcType=VARCHAR}
AND T2.CASH_TYPE_2 = #{cashType2,jdbcType=VARCHAR}
AND T3.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
order by T1.EFF_DATE ASC

SELECT DISTINCT T2.FEE_ID id, T4.FEE_NAME text FROM FIN_CASH_CALC_RULE T1 INNER JOIN FIN_CASH_INFO T2 ON T2.CASH_ID = T1.CASH_ID LEFT JOIN MST_FEEINFO T4 ON T2.FEE_ID = T4.FEE_ID LEFT JOIN FIN_PRODUCT T3 ON T3.FINPROD_ID = T1.FINPROD_ID AND T2.FINPROD_ID = T3.FINPROD_ID
AND T2.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
and T2.CASH_TYPE_2 in ('C11','C12','C13','C14')
AND T2.CASH_TYPE_1 = #{cashType1,jdbcType=VARCHAR}
AND T2.CASH_TYPE_2 = #{cashType2,jdbcType=VARCHAR}
AND T3.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and (T4.FEE_ID like concat(concat('%', #{search}), '%') or T4.FEE_NAME like concat(concat('%', #{search}), '%'))
and (T4.FEE_ID IN (#{initValue}) or T4.FEE_NAME IN (#{initValue}))

SELECT T3.FINPROD_ID, T3.FINPROD_TYPE, T3.FINPROD_TYPE2, T3.FINPROD_MARKET_ID, T3.FINPROD_NAME, T3.FINPROD_ABBR, T3.ISSUE_AMT, T3.VDATE, T1.EFF_DATE, T1.CALC_TYPE, T1.BASE_TYPE, T1.BASE_DATE_TYPE, T1.BASIS, T1.YIELD*100 YIELD, T1.IS_INITIAL, T1.BRANCH, T2.CASH_ID, T2.FEE_ID FROM FIN_CASH_CALC_RULE T1 LEFT JOIN FIN_PRODUCT T3 ON T3.FINPROD_ID = T1.FINPROD_ID INNER JOIN FIN_CASH_INFO T2 ON T2.CASH_ID = T1.CASH_ID AND T2.FINPROD_ID = T3.FINPROD_ID
AND T2.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
AND T2.CASH_TYPE_1 = #{cashType1,jdbcType=VARCHAR}
AND T2.CASH_TYPE_2 = #{cashType2,jdbcType=VARCHAR}
AND T1.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
order by T1.EFF_DATE ASC

    	SELECT
			T1.EFF_DATE,
			T1.BASIS,
			T1.YIELD 
		FROM
			FIN_CASH_CALC_RULE T1
			LEFT JOIN FIN_CASH_INFO T2 ON T2.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
			AND T2.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
			AND T2.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
			AND T2.CASH_ID = T1.CASH_ID 
			where T1.FINPROD_ID= #{finprodId,jdbcType=VARCHAR}
			AND T1.IS_INITIAL = #{isInitial,jdbcType=VARCHAR}
